  XW += x[18] * 4.1073000000000000e+01; // aC3H5
  XW += x[19] * 4.2081000000000003e+01; // C3H6
  XW += x[20] * 5.6064000000000000e+01; // C2H3CHO
  XW += x[21] * 5.5099999999999994e+01; // C4H7
  XW += x[22] * 5.6107999999999997e+01; // C4H81
