  amrex::Real XW = 0; // See Eq 4, 11 in CK Manual
  amrex::Real ROW;
  // Compute mean molecular wt first
  XW += x[0] * 1.7034000000000000e+02;  // NC12H26
  XW += x[1] * 1.0080000000000000e+00;  // H
